CREATE VIEW v_player_stats AS SELECT Player.id AS player_id, Player.player_api_id, Player.player_name, Player.birthday, Player.height, Player.weight, Player_Attributes.date AS attribute_date, Player_Attributes.overall_rating, Player_Attributes.potential, Player_Attributes.preferred_foot, Player_Attributes.attacking_work_rate, Player_Attributes.defensive_work_rate, Player_Attributes.crossing, Player_Attributes.finishing, Player_Attributes.heading_accuracy, Player_Attributes.short_passing, Player_Attributes.dribbling, Player_Attributes.free_kick_accuracy, Player_Attributes.ball_control, Player_Attributes.acceleration, Player_Attributes.sprint_speed, Player_Attributes.stamina, Player_Attributes.strength, Player_Attributes.penalties, Player.player_fifa_api_id, Player_Attributes.id, Player_Attributes.player_fifa_api_id AS Player_Attributes_player_fifa_api_id, Player_Attributes.player_api_id AS Player_Attributes_player_api_id, Player_Attributes.volleys, Player_Attributes.curve, Player_Attributes.long_passing, Player_Attributes.agility, Player_Attributes.reactions, Player_Attributes.balance, Player_Attributes.shot_power, Player_Attributes.jumping, Player_Attributes.long_shots, Player_Attributes.aggression, Player_Attributes.interceptions, Player_Attributes.positioning, Player_Attributes.vision, Player_Attributes.marking, Player_Attributes.standing_tackle, Player_Attributes.sliding_tackle, Player_Attributes.gk_diving, Player_Attributes.gk_handling, Player_Attributes.gk_kicking, Player_Attributes.gk_positioning, Player_Attributes.gk_reflexes FROM Player LEFT JOIN Player_Attributes ON Player.player_api_id = Player_Attributes.player_api_id;

CREATE VIEW v_team_stats AS SELECT Team.id AS team_id, Team.team_api_id, Team.team_long_name, Team.team_short_name, Team_Attributes.date AS attribute_date, Team_Attributes.buildUpPlaySpeed AS build_up_play_speed, Team_Attributes.buildUpPlayPassing AS build_up_play_passing, Team_Attributes.chanceCreationPassing AS chance_creation_passing, Team_Attributes.chanceCreationCrossing AS chance_creation_crossing, Team_Attributes.chanceCreationShooting AS chance_creation_shooting, Team_Attributes.defencePressure AS defence_pressure, Team_Attributes.defenceAggression AS defence_aggression, Team_Attributes.defenceTeamWidth AS defence_team_width, Team.team_fifa_api_id, Team_Attributes.id, Team_Attributes.team_fifa_api_id AS Team_Attributes_team_fifa_api_id, Team_Attributes.team_api_id AS Team_Attributes_team_api_id, Team_Attributes.buildUpPlaySpeedClass, Team_Attributes.buildUpPlayDribbling, Team_Attributes.buildUpPlayDribblingClass, Team_Attributes.buildUpPlayPassingClass, Team_Attributes.buildUpPlayPositioningClass, Team_Attributes.chanceCreationPassingClass, Team_Attributes.chanceCreationCrossingClass, Team_Attributes.chanceCreationShootingClass, Team_Attributes.chanceCreationPositioningClass, Team_Attributes.defencePressureClass, Team_Attributes.defenceAggressionClass, Team_Attributes.defenceTeamWidthClass, Team_Attributes.defenceDefenderLineClass FROM Team LEFT JOIN Team_Attributes ON Team.team_api_id = Team_Attributes.team_api_id;

CREATE VIEW v_match_details AS SELECT Match.id AS match_id, Match.season, Match.stage, Match.date AS match_date, Match.home_team_goal, Match.away_team_goal, League.name AS league_name, Country.name AS country_name, home_team.team_long_name AS home_team_name, away_team.team_long_name AS away_team_name, Match.country_id, Match.league_id, Match.match_api_id, Match.home_team_api_id, Match.away_team_api_id, Match.home_player_X1, Match.home_player_X2, Match.home_player_X3, Match.home_player_X4, Match.home_player_X5, Match.home_player_X6, Match.home_player_X7, Match.home_player_X8, Match.home_player_X9, Match.home_player_X10, Match.home_player_X11, Match.away_player_X1, Match.away_player_X2, Match.away_player_X3, Match.away_player_X4, Match.away_player_X5, Match.away_player_X6, Match.away_player_X7, Match.away_player_X8, Match.away_player_X9, Match.away_player_X10, Match.away_player_X11, Match.home_player_Y1, Match.home_player_Y2, Match.home_player_Y3, Match.home_player_Y4, Match.home_player_Y5, Match.home_player_Y6, Match.home_player_Y7, Match.home_player_Y8, Match.home_player_Y9, Match.home_player_Y10, Match.home_player_Y11, Match.away_player_Y1, Match.away_player_Y2, Match.away_player_Y3, Match.away_player_Y4, Match.away_player_Y5, Match.away_player_Y6, Match.away_player_Y7, Match.away_player_Y8, Match.away_player_Y9, Match.away_player_Y10, Match.away_player_Y11, Match.home_player_1, Match.home_player_2, Match.home_player_3, Match.home_player_4, Match.home_player_5, Match.home_player_6, Match.home_player_7, Match.home_player_8, Match.home_player_9, Match.home_player_10, Match.home_player_11, Match.away_player_1, Match.away_player_2, Match.away_player_3, Match.away_player_4, Match.away_player_5, Match.away_player_6, Match.away_player_7, Match.away_player_8, Match.away_player_9, Match.away_player_10, Match.away_player_11, Match.goal, Match.shoton, Match.shotoff, Match.foulcommit, Match.card, Match.cross, Match.corner, Match.possession, Match.B365H, Match.B365D, Match.B365A, Match.BWH, Match.BWD, Match.BWA, Match.IWH, Match.IWD, Match.IWA, Match.LBH, Match.LBD, Match.LBA, Match.PSH, Match.PSD, Match.PSA, Match.WHH, Match.WHD, Match.WHA, Match.SJH, Match.SJD, Match.SJA, Match.VCH, Match.VCD, Match.VCA, Match.GBH, Match.GBD, Match.GBA, Match.BSH, Match.BSD, Match.BSA, League.id, League.country_id AS League_country_id, Country.id AS Country_id_2, home_team.id AS home_team_id, home_team.team_api_id, home_team.team_fifa_api_id, home_team.team_short_name, away_team.id AS away_team_id, away_team.team_api_id AS away_team_team_api_id, away_team.team_fifa_api_id AS away_team_team_fifa_api_id, away_team.team_short_name AS away_team_team_short_name FROM Match LEFT JOIN League ON Match.league_id = League.id LEFT JOIN Country ON Match.country_id = Country.id LEFT JOIN Team AS home_team ON Match.home_team_api_id = home_team.team_api_id LEFT JOIN Team AS away_team ON Match.away_team_api_id = away_team.team_api_id;
